sys_variable_value.value:
(function execute(inputs, outputs) {
  var createdBy = inputs.created_by;
  var isAdmin = false;

  gs.info('DEBUG: created_by received = ' + createdBy);

  if (!createdBy) {
    gs.info('DEBUG: created_by is empty');
    outputs.is_admin = false;
    return;
  }

  var userSysId = '';
  var userGR = new GlideRecord('sys_user');
  userGR.addQuery('sys_id', createdBy);
  userGR.query();
  if (userGR.next()) {
    userSysId = userGR.getUniqueValue();
    gs.info('DEBUG: Found user by sys_id = ' + userGR.name);
  } else {
    userGR = new GlideRecord('sys_user');
    userGR.addQuery('user_name', createdBy);
    userGR.query();
    if (userGR.next()) {
      userSysId = userGR.getUniqueValue();
      gs.info('DEBUG: Found user by username = ' + userGR.user_name);
    } else {
      gs.info('DEBUG: No user found for input = ' + createdBy);
    }
  }

  if (userSysId) {
    var roleGR = new GlideRecord('sys_user_has_role');
    roleGR.addQuery('user', userSysId);
    roleGR.query();
    gs.info('DEBUG: Checking roles for user ' + userSysId);
    while (roleGR.next()) {
      var roleName = roleGR.role.name.toString();
      gs.info('DEBUG: Found role: ' + roleName);
      if (roleName === 'x_1805892_compan_0.admin') {
        isAdmin = true;
        gs.info('DEBUG: MATCH FOUND! User is admin.');
        break;
      }
    }
  }

  outputs.is_admin = isAdmin;
  gs.info('DEBUG: Final is_admin = ' + isAdmin);
})(inputs, outputs);

